from pathlib import Path

INDEX = Path('app/src/main/assets/index.html')
text = INDEX.read_text(encoding='utf-8')

needle = 'function renderIceDay(){const start=monday(selected);'
if needle not in text:
    raise SystemExit('Violet event timeline: renderIceDay marker not found')

helpers = r'''
const VIOLET_EMPTY_HOUR=24;
const VIOLET_BUSY_HOUR=84;
let violetEditorIndex=null,violetSwipeState=null,violetIgnoreClick=false;
function violetClockMinutes(value){const m=/^(\d{2}):(\d{2})$/.exec(value||'');if(!m)return 0;return Math.max(0,Math.min(1439,Number(m[1])*60+Number(m[2])))}
function violetDefaultEnd(start){const end=Math.min(1439,violetClockMinutes(start)+30),h=Math.floor(end/60),m=end%60;return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')}
function violetTaskEnd(row){const s=violetClockMinutes(row?.time),raw=row?.endTime;return /^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(raw||'')&&violetClockMinutes(raw)>s?raw:violetDefaultEnd(row?.time||'00:00')}
function violetBuildLayout(rows){
 const busy=Array(24).fill(false);
 rows.forEach(r=>{const s=violetClockMinutes(r.time),e=Math.max(s+1,violetClockMinutes(violetTaskEnd(r)));for(let h=0;h<24;h++){if(s<(h+1)*60&&e>h*60)busy[h]=true}});
 const heights=busy.map(v=>v?VIOLET_BUSY_HOUR:VIOLET_EMPTY_HOUR),tops=[0];
 for(let h=0;h<24;h++)tops[h+1]=tops[h]+heights[h];
 const y=minute=>{const m=Math.max(0,Math.min(1440,minute)),h=Math.min(23,Math.floor(m/60));if(m>=1440)return tops[24];return tops[h]+((m-h*60)/60)*heights[h]};
 const positions={};
 rows.forEach(r=>{const s=violetClockMinutes(r.time),e=Math.max(s+15,violetClockMinutes(violetTaskEnd(r)));positions[r.i]={top:y(s),height:Math.max(30,y(e)-y(s))}});
 return {busy,heights,tops,y,positions,total:tops[24]};
}
function violetTimelineAxis(layout){return Array.from({length:25},(_,h)=>`<time style="top:${(layout.tops[h]??layout.total).toFixed(2)}px">${String(h).padStart(2,'0')}:00</time>`).join('')}
function violetTimelineLines(layout){return Array.from({length:25},(_,h)=>`<i class="violet-hour-line" style="top:${(layout.tops[h]??layout.total).toFixed(2)}px"></i>`).join('')}
function violetEventMarkup(r,layout){const m=layout.positions[r.i],black=r.color==='black',rem=linkedReminder(selected,r.i),bell=rem?.enabled?'●':'';return `<div class="violet-event-wrap" data-violet-wrap="${r.i}" style="--vt-top:${m.top.toFixed(2)}px;--vt-height:${m.height.toFixed(2)}px;${iceRowStyle(r.color)}"><div class="violet-event-actions"><button type="button" data-color-open="${r.i}" aria-label="Цвет задания"><span class="violet-action-dot" style="background:${iceColor(r.color)[1]}"></span><small>Цвет</small></button><button type="button" data-slot-reminder="${r.i}" aria-label="Напоминание">${uiIcon('bell')}<small>Напомнить</small></button><button type="button" class="violet-delete-task" data-violet-delete="${r.i}" aria-label="Удалить">${uiIcon('trash')}<small>Удалить</small></button></div><button type="button" class="violet-event-card ${black?'is-black':''}" data-violet-open="${r.i}"><span class="violet-event-range">${r.time} – ${violetTaskEnd(r)}</span><strong>${esc(r.text)}</strong>${bell?`<i class="violet-reminder-mark" aria-label="Уведомление включено">${bell}</i>`:''}</button></div>`}
function violetEditorMarkup(){return `<section id="violet-task-editor" class="violet-task-editor" hidden><div class="violet-editor-head"><strong id="violet-editor-title">Новое задание</strong><button type="button" id="violet-editor-close" aria-label="Закрыть">×</button></div><label class="violet-editor-text"><span>Задание</span><textarea id="violet-editor-text" rows="2" maxlength="10000" placeholder="Что нужно сделать?"></textarea></label><div class="violet-editor-times"><label><span>С</span><input id="violet-editor-start" type="time" step="60"></label><label><span>До</span><input id="violet-editor-end" type="time" step="60"></label></div><p id="violet-editor-error" class="violet-editor-error" hidden></p><button type="button" id="violet-editor-done">Готово</button></section>`}
function violetSyncMenuButton(){const b=$('ice-add');if(!b)return;b.setAttribute('aria-label','Меню');b.setAttribute('title','Меню')}
function renderVioletTimelineDay(){const start=monday(selected),rows=slots().map((r,i)=>({...r,i})).filter(r=>r.text.trim()).sort((a,b)=>a.time.localeCompare(b.time)||a.i-b.i),layout=violetBuildLayout(rows);$('view').innerHTML=`<section class="ice-home violet-event-home"><header class="ice-hero ice-tribute"><div class="ice-tribute-glow" aria-hidden="true"></div><div class="ice-tupac-photo"><img src="ice/new-york-city.jpg" alt="" decoding="async"></div><div class="ice-date-line"><span>${esc(fmt(selected,{weekday:'long',day:'numeric',month:'long'}))}${FRIEND_SHIFT?`<small class="friend-shift-title">${friendShiftText(selected)}</small>`:''}</span></div></header><nav class="ice-week" aria-label="Дни недели">${Array.from({length:7},(_,i)=>{const d=addDays(start,i),count=occupied(d)+dayEvents(d).length;return `<button data-date="${d}" class="${i>=5?'ice-sunday':''}" ${d===selected?'aria-current="date"':''} aria-label="${fmt(d,{weekday:'long',day:'numeric',month:'long'})}"><span>${fmt(d,{weekday:'short'})}</span><strong>${dateObj(d).getDate()}</strong><i class="${count?'has-plans':''}"></i></button>`}).join('')}</nav><div class="ice-paper violet-event-paper"><div class="violet-event-timeline" style="--vt-total:${layout.total}px"><div class="violet-event-axis">${violetTimelineAxis(layout)}</div><div class="violet-event-track">${violetTimelineLines(layout)}${rows.map(r=>violetEventMarkup(r,layout)).join('')}</div></div></div>${violetEditorMarkup()}<button type="button" id="violet-add-task" class="violet-add-task" aria-label="Добавить задание">+</button></section>`;requestAnimationFrame(()=>{violetSyncMenuButton();const paper=document.querySelector('.violet-event-paper');if(!paper)return;const today=selected===iso(),first=rows[0];const minute=today?(new Date().getHours()*60+new Date().getMinutes()):(first?violetClockMinutes(first.time):8*60);paper.scrollTop=Math.max(0,layout.y(minute)-120)})}
function violetOpenEditor(index=null){const rows=ensureHourlyDay(selected),panel=$('violet-task-editor');if(!panel)return;violetEditorIndex=index;const edit=index!==null&&index>=0,row=edit?rows[index]:null;const now=new Date(),defaultStart=String(now.getHours()).padStart(2,'0')+':'+String(Math.floor(now.getMinutes()/5)*5).padStart(2,'0');$('violet-editor-title').textContent=edit?'Изменить задание':'Новое задание';$('violet-editor-text').value=row?.text||'';$('violet-editor-start').value=row?.time||defaultStart;$('violet-editor-end').value=row?violetTaskEnd(row):violetDefaultEnd(defaultStart);$('violet-editor-error').hidden=true;panel.hidden=false;document.body.classList.add('violet-editor-open');setTimeout(()=>$('violet-editor-text')?.focus(),40)}
function violetCloseEditor(){const panel=$('violet-task-editor');if(panel)panel.hidden=true;document.body.classList.remove('violet-editor-open');violetEditorIndex=null;try{window.AndroidFiles?.hideKeyboard?.()}catch(e){}}
function violetOverlap(rows,index,start,end){return rows.some((r,i)=>i!==index&&r.text.trim()&&start<violetClockMinutes(violetTaskEnd(r))&&end>violetClockMinutes(r.time))}
function violetSaveEditor(){const rows=ensureHourlyDay(selected),textValue=$('violet-editor-text').value.trim(),start=$('violet-editor-start').value,end=$('violet-editor-end').value,s=violetClockMinutes(start),e=violetClockMinutes(end),error=$('violet-editor-error');if(!textValue){error.textContent='Напиши задание.';error.hidden=false;return}if(!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(start)||!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(end)||e<=s){error.textContent='Время «До» должно быть позже времени «С».';error.hidden=false;return}let index=violetEditorIndex;if(index===null){index=rows.findIndex(r=>!r.text.trim());if(index<0){error.textContent='На этот день уже добавлено максимальное количество заданий.';error.hidden=false;return}}if(violetOverlap(rows,index,s,e)){error.textContent='Этот промежуток пересекается с другим заданием.';error.hidden=false;return}const row=rows[index],oldTime=row.time;row.text=textValue;row.time=start;row.endTime=end;if(!row.color)row.color='none';state.reminders.filter(r=>r.date===selected&&r.slot>=0&&reminderIndex(r,selected)===index).forEach(r=>r.time=start);if(!persist()){row.time=oldTime;return}violetCloseEditor();render()}
function violetDeleteTask(index){const rows=ensureHourlyDay(selected),row=rows[index];if(!row)return;row.text='';row.color='none';row.time=String(index).padStart(2,'0')+':00';delete row.endTime;state.reminders=state.reminders.filter(r=>!(r.date===selected&&r.slot>=0&&reminderIndex(r,selected)===index));persist();render()}
function violetCloseSwipes(except=null){document.querySelectorAll('.violet-event-wrap.revealed').forEach(el=>{if(el!==except)el.classList.remove('revealed')})}
'''
text=text.replace(needle,helpers+"\nfunction renderIceDay(){if(state.prefs.variant==='violet')return renderVioletTimelineDay();const start=monday(selected);",1)

marker="let iceTimeIndex=-1,iceTimeDate='';"
if marker not in text:
    raise SystemExit('Violet event timeline: listener marker not found')
listeners=r'''
document.addEventListener('click',e=>{if(state.prefs?.variant!=='violet'||tab!=='day')return;const b=e.target.closest('button');if(!b)return;if(b.id==='violet-add-task'){violetCloseSwipes();violetOpenEditor(null);return}if(b.id==='violet-editor-close'){violetCloseEditor();return}if(b.id==='violet-editor-done'){violetSaveEditor();return}if(b.dataset.violetDelete!==undefined){violetDeleteTask(Number(b.dataset.violetDelete));return}if(b.dataset.violetOpen!==undefined){if(violetIgnoreClick){violetIgnoreClick=false;return}violetCloseSwipes();violetOpenEditor(Number(b.dataset.violetOpen));return}if(b.dataset.pickColor){setTimeout(()=>{if(state.prefs?.variant==='violet'&&tab==='day')render()},0)}});
document.addEventListener('pointerdown',e=>{if(state.prefs?.variant!=='violet'||tab!=='day')return;const card=e.target.closest('.violet-event-card');if(!card)return;violetSwipeState={card,wrap:card.closest('.violet-event-wrap'),x:e.clientX,y:e.clientY,moved:false};card.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{const s=violetSwipeState;if(!s)return;const dx=e.clientX-s.x,dy=e.clientY-s.y;if(Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy)){s.moved=true;const base=s.wrap.classList.contains('revealed')?-168:0;const x=Math.max(-168,Math.min(0,base+dx));s.card.style.transform=`translateX(${x}px)`;e.preventDefault()}} ,{passive:false});
document.addEventListener('pointerup',e=>{const s=violetSwipeState;if(!s)return;const dx=e.clientX-s.x;s.card.style.transform='';if(s.moved){violetIgnoreClick=true;if((s.wrap.classList.contains('revealed')&&dx>45)||(!s.wrap.classList.contains('revealed')&&dx>-45))s.wrap.classList.remove('revealed');else{violetCloseSwipes(s.wrap);s.wrap.classList.add('revealed')}}violetSwipeState=null});
'''
text=text.replace(marker,listeners+'\n'+marker,1)

INDEX.write_text(text,encoding='utf-8')
print('Violet compact event timeline applied')
